10	  'Review the finding and suggested fix, then validate the affected code path before merging.';
11	// Cap fingerprint input so minor rephrasing of long findings still hashes to the same id
12	// while staying long enough to distinguish unrelated findings on the same file/severity.
13	const FINGERPRINT_FINDING_MAX_CHARS = 160;
14	
15	type SarifRule = SarifLog['runs'][number]['tool']['driver']['rules'][number];
16	
17	const SARIF_RULE: SarifRule = {
18	  id: GENERIC_RULE_ID,
19	  name: 'Promptfoo Code Scan Finding',
20	  shortDescription: {
21	    text: 'Potential LLM security issue identified by Promptfoo Code Scan.',
22	  },
23	  fullDescription: {
24	    text: 'Promptfoo Code Scan reviews code changes for LLM-related security risks such as prompt injection, unsafe tool use, and sensitive data exposure.',
25	  },
26	  defaultConfiguration: { level: 'warning' },
27	  help: { text: RULE_HELP_TEXT, markdown: RULE_HELP_TEXT },
28	  // 'medium' is the SARIF spec's heuristic-grade tag (very-high|high|medium|low|very-low).
29	  // It signals to GitHub Code Scanning that these findings are model-derived rather than
30	  // deterministic AST matches, which affects ranking and dedup behavior.
31	  properties: { tags: ['security', 'llm-security'], precision: 'medium' },
