111	function isReportableFinding(comment: Comment): boolean {
112	  // GitHub Code Scanning needs an artifact location to display a result, so we require
113	  // `file`. `line` is optional — SARIF allows results without a region (file-level
114	  // findings). CommentSchema marks `severity` optional and toSarifLevel falls back to
115	  // 'note' for undefined, so we let undefined flow through rather than silently dropping
116	  // a finding the scanner couldn't grade. Explicit NONE means "no issue" and is filtered.
117	  const hasFile = comment.file != null && comment.file !== '';
118	  return hasFile && comment.severity !== CodeScanSeverity.NONE;
119	}
