121	function toSarifLevel(severity: CodeScanSeverity | undefined): SarifResult['level'] {
122	  if (severity === undefined) {
123	    return 'note';
124	  }
125	  switch (severity) {
126	    case CodeScanSeverity.CRITICAL:
127	    case CodeScanSeverity.HIGH:
128	      return 'error';
129	    case CodeScanSeverity.MEDIUM:
130	      return 'warning';
131	    case CodeScanSeverity.LOW:
132	    case CodeScanSeverity.NONE:
133	      // NONE is filtered upstream by isReportableFinding; kept here for exhaustiveness.
134	      return 'note';
135	    default: {
136	      // Compile-time exhaustiveness: adding a CodeScanSeverity value forces this to break.
137	      const _exhaustive: never = severity;
138	      return _exhaustive;
139	    }
140	  }
141	}
