177	  if (comment.line) {
178	    const startLine = comment.startLine ?? comment.line;
179	    const endLine = comment.line;
180	    const region: SarifRegion = { startLine };
181	    if (endLine > startLine) {
182	      region.endLine = endLine;
183	    }
184	    physicalLocation.region = region;
185	  }
186	
187	  return [{ physicalLocation }];
